type OrganizationMemberRole = "Owner" | "Admin" | "Member";

function isKnownMemberRole(role: unknown): role is OrganizationMemberRole {
  return role === "Owner" || role === "Admin" || role === "Member";
}

function isEditableMemberRole(role: unknown): role is "Admin" | "Member" {
  return role === "Admin" || role === "Member";
}

function useLocale() {
  const { i18n } = useTranslation();
  return i18n.language === "pt-BR" ? "pt-BR" : "en-US";
}

function useSelectedOrganization() {
  const { user } = useAuth();
  const selectedId = useOrganizationStore((state) => state.selectedOrganizationId);
  const id = user?.organizations.some((organization) => organization.id === selectedId) ? selectedId : user?.organizations[0]?.id ?? null;
  return id;
}

function LoadingState({ label }: { label?: string }) {
  const { t } = useTranslation();
  return <div className="empty-state" role="status"><span className="empty-state__icon"><Sparkles size={22} /></span><h3>{label ?? t("common.loading")}</h3></div>;
}

function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) {
  const { t } = useTranslation();
  return <EmptyState icon={RotateCcw} title={t("errors.attention")} description={message} action={<Button variant="secondary" onClick={onRetry}>{t("errors.tryAgain")}</Button>} />;
}

function ProtectedRoute({ children }: { children: ReactNode }) {
  const { t } = useTranslation();
  const auth = useAuth();
  const location = useLocation();
  if (auth.status === "initializing") return <LoadingState label={t("auth.protectedSession")} />;
  if (auth.status !== "authenticated") {
    const returnTo = `${location.pathname}${location.search}`;
    return <Navigate to={`/auth/sign-in?returnTo=${encodeURIComponent(returnTo)}`} replace />;
  }
  if (!auth.user?.organizations.length && location.pathname !== "/account/create-organization") return <Navigate to="/account/create-organization" replace />;
  return <>{children}</>;
}

