function safeReturnTo(value: string | null) {
  return value?.startsWith("/") && !value.startsWith("//") ? value : "/dashboard";
}

function AuthPage({ mode }: { mode: "sign-in" | "sign-up" }) {
  const { t, i18n } = useTranslation();
  const auth = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const isSignIn = mode === "sign-in";
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setError("");
    const data = new FormData(event.currentTarget);
    const schema = z.object({ email: z.string().email(), password: z.string().min(isSignIn ? 1 : 8) });
    const values = { email: String(data.get("email") ?? ""), password: String(data.get("password") ?? "") };
    const parsed = schema.safeParse(values);
    if (!parsed.success) { setError(isSignIn ? t("auth.validCredentials") : t("auth.validRegistration")); return; }
    setPending(true);
    try {
      const user = await auth.signIn(isSignIn ? values : { ...values, firstName: String(data.get("firstName") ?? ""), lastName: String(data.get("lastName") ?? "") });
      toast.success(isSignIn ? t("auth.welcomeBack") : t("auth.accountCreated"));
      navigate(user.organizations.length ? safeReturnTo(searchParams.get("returnTo")) : "/account/create-organization", { replace: true });
    } catch (nextError) { setError(nextError instanceof Error ? nextError.message : t("auth.unableContinue")); }
    finally { setPending(false); }
  };
  return <PublicLayout><main className="auth-layout"><section className="auth-aside"><div className="auth-aside__inner"><p className="eyebrow"><span className="eyebrow-mark" />BitFinance / {t("common.financeDesk")}</p><h1>{isSignIn ? t("auth.signInTitle") : t("auth.signUpTitle")}</h1><p>{isSignIn ? t("auth.signInBody") : t("auth.signUpBody")}</p><div className="auth-aside__note"><Sparkles size={18} /><span>{isSignIn ? t("auth.protectedSession") : t("auth.minimumPassword")}</span></div></div><div className="auth-aside__stamp">BF / live</div></section><section className="auth-panel"><div className="auth-panel__top"><Link to="/" className="back-link">← {t("common.backHome")}</Link><button className="language-switch" onClick={() => { const next = i18n.language === "en-US" ? "pt-BR" : "en-US"; void i18n.changeLanguage(next); localStorage.setItem("bitfinance-v2-locale", next); }}>{i18n.language === "en-US" ? "EN" : "PT"}</button></div><form className="auth-form" onSubmit={submit}><div className="auth-form__heading"><span className="auth-form__icon">{isSignIn ? <LockKeyhole size={21} /> : <UserPlus size={21} />}</span><div><p className="eyebrow">01 / {isSignIn ? t("auth.signInStep") : t("auth.getStarted")}</p><h2>{isSignIn ? t("common.signIn") : t("common.signUp")}</h2></div></div>{!isSignIn && <div className="form-grid"><label><span>{t("auth.firstName")}</span><input name="firstName" autoComplete="given-name" required /></label><label><span>{t("auth.lastName")}</span><input name="lastName" autoComplete="family-name" required /></label></div>}<label><span>{t("auth.email")}</span><div className="input-with-icon"><Mail size={17} /><input name="email" type="email" autoComplete="email" required /></div></label><label><span>{t("auth.password")}</span><input name="password" type="password" autoComplete={isSignIn ? "current-password" : "new-password"} minLength={isSignIn ? 1 : 8} required /></label>{error && <p className="form-error" role="alert">{error}</p>}<Button type="submit" disabled={pending} className="button--full button--large">{pending ? t("common.loading") : isSignIn ? t("common.signIn") : t("common.continue")} {!pending && <ArrowUpRight size={17} />}</Button><p className="auth-form__switch">{isSignIn ? t("auth.noAccount") : t("auth.haveAccount")} <Link to={isSignIn ? "/auth/sign-up" : "/auth/sign-in"}>{isSignIn ? t("common.signUp") : t("common.signIn")}</Link></p></form><div className="auth-panel__footer"><span><ShieldCheck size={14} /> {t("auth.serverData")}</span></div></section></main></PublicLayout>;
}

function JoinPage() {
  const { t } = useTranslation();
  const auth = useAuth(); const [params] = useSearchParams(); const token = params.get("token"); const navigate = useNavigate(); const [message, setMessage] = useState("");
  const join = useMutation({
    mutationFn: async () => {
      const previousOrganizationIds = new Set(auth.user?.organizations.map((organization) => organization.id) ?? []);
      await organizationsService.joinAsync(token!);
      return previousOrganizationIds;
    },
    onSuccess: async (previousOrganizationIds) => {
      const nextUser = await auth.refreshUser();
      const joinedOrganization = nextUser.organizations.find((organization) => !previousOrganizationIds.has(organization.id));
      const selectedOrganization = joinedOrganization ?? nextUser.organizations[0];
      if (selectedOrganization) useOrganizationStore.getState().setSelectedOrganizationId(selectedOrganization.id);
      toast.success(t("join.joined"));
      navigate("/dashboard", { replace: true });
    },
    onError: (error) => setMessage(error instanceof Error ? error.message : t("join.invalid")),
  });
  const signInUrl = `/auth/sign-in?returnTo=${encodeURIComponent(`/join-organization?token=${encodeURIComponent(token ?? "")}`)}`;
  return <PublicLayout><main className="center-page"><div className="center-card"><span className="center-card__icon"><UsersRound size={25} /></span><p className="eyebrow">{t("join.eyebrow")}</p><h1>{token ? t("join.title") : t("join.missingTitle")}</h1><p>{token ? t("join.body") : t("join.missingBody")}</p>{message && <p className="form-error" role="alert">{message}</p>}{auth.status === "authenticated" && token ? <Button disabled={join.isPending} onClick={() => join.mutate()}>{join.isPending ? t("common.loading") : t("common.continue")} <ArrowRight size={16} /></Button> : <Link to={signInUrl} className="button button--primary">{t("common.signIn")} <ArrowRight size={16} /></Link>}</div></main></PublicLayout>;
}

function CreateOrganizationPage() {
  const { t } = useTranslation(); const auth = useAuth(); const navigate = useNavigate(); const [name, setName] = useState("");
  const create = useMutation({ mutationFn: () => organizationsService.createAsync(name.trim()), onSuccess: async (organization) => { await auth.refreshUser(); useOrganizationStore.getState().setSelectedOrganizationId(organization.id); toast.success(t("createOrganization.created")); navigate("/dashboard", { replace: true }); } });
  if (auth.status === "initializing") return <LoadingState label={t("createOrganization.preparing")} />;
  return <PublicLayout><main className="center-page"><div className="center-card center-card--wide"><span className="center-card__icon"><Home size={25} /></span><p className="eyebrow">{t("createOrganization.eyebrow")}</p><h1>{t("createOrganization.title")}</h1><p>{t("createOrganization.body")}</p><label className="field-label"><span>{t("createOrganization.workspaceName")}</span><input value={name} onChange={(event) => setName(event.target.value)} required /></label>{create.error && <p className="form-error" role="alert">{create.error instanceof Error ? create.error.message : t("createOrganization.unable")}</p>}<Button disabled={!name.trim() || create.isPending || auth.status !== "authenticated"} onClick={() => create.mutate()}>{create.isPending ? t("createOrganization.creating") : t("common.continue")} <ArrowRight size={16} /></Button></div></main></PublicLayout>;
}

function useCurrentMonth() {
  const [searchParams] = useSearchParams();
  const fromParam = searchParams.get("from");
  const toParam = searchParams.get("to");
  return useMemo(() => {
    const now = new Date();
    const fallback = { from: new Date(now.getFullYear(), now.getMonth(), 1), to: new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999) };
    const parse = (value: string | null, endOfDay = false) => {
      if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
      const date = new Date(`${value}T${endOfDay ? "23:59:59.999" : "00:00:00.000"}`);
      return Number.isNaN(date.getTime()) ? null : date;
    };
    const from = parse(fromParam);
    const to = parse(toParam, true);
    return from && to && from <= to ? { from, to } : fallback;
  }, [fromParam, toParam]);
}

function DashboardPage() {
  const { t } = useTranslation(); const locale = useLocale(); const organizationId = useSelectedOrganization(); const month = useCurrentMonth(); const { user } = useAuth(); const queries = useDashboardQueries(organizationId, month.from, month.to); const summary = queries.summary.data; const upcoming = queries.upcoming.data ?? []; const recent = queries.recent.data ?? [];
  if (!organizationId) return <PageContainer><EmptyState icon={Building2} title={t("dashboard.createOrganization")} description={t("dashboard.needsOrganization")} action={<Link to="/account/create-organization" className="button button--primary">{t("dashboard.createWorkspace")}</Link>} /></PageContainer>;
  const loading = queries.summary.isPending || queries.upcoming.isPending || queries.recent.isPending; const failed = queries.summary.error || queries.upcoming.error || queries.recent.error; const name = user?.fullName.split(" ")[0] ?? t("dashboard.greetingFallback"); const budgetLabel = summary?.monthlyBudget == null ? t("dashboard.notSet") : formatCurrency(summary.monthlyBudget, locale); const spent = summary?.spentThisMonth ?? 0; const spentPercentage = summary?.spentPercentage ?? 0;
  return <PageContainer><PageHeader eyebrow={t("dashboard.eyebrow")} title={t("common.titleWithName", { title: t("dashboard.title"), name })} description={t("dashboard.body")} actions={<div className="period-control"><span className="period-control__dot" />{formatDate(month.from.toISOString(), locale)} — {formatDate(month.to.toISOString(), locale)} <ChevronRight size={14} /></div>} />{loading && !summary ? <LoadingState /> : failed && !summary ? <ErrorState message={t("dashboard.dataUnavailable")} onRetry={() => { void queries.summary.refetch(); void queries.upcoming.refetch(); void queries.recent.refetch(); }} /> : <><div className="dashboard-intro"><div><span className="dashboard-intro__label">{t("dashboard.onTrack")}</span><p>{t("dashboard.committedMoney", { amount: formatCurrency(summary?.upcomingBillsAmount ?? 0, locale) })}</p></div></div><div className="metrics-grid"><MetricCard label={t("dashboard.budget")} value={budgetLabel} detail={summary?.monthlyBudget == null ? t("dashboard.configureLimit") : t("dashboard.currentLimit")} icon={WalletCards} tone="blue" progress={summary?.monthlyBudget == null ? undefined : spentPercentage} /><MetricCard label={t("dashboard.spent")} value={formatCurrency(spent, locale)} detail={summary?.monthlyBudget == null ? t("dashboard.noBudget") : `${spentPercentage}% ${t("dashboard.budgetUsed")}`} icon={BarChart3} tone="mint" /><MetricCard label={t("dashboard.remaining")} value={summary?.remainingBudget == null ? t("dashboard.notSet") : formatCurrency(summary.remainingBudget, locale)} detail={t("dashboard.availableToSpend")} icon={CircleDollarSign} tone="ink" /><MetricCard label={t("dashboard.upcoming")} value={formatCurrency(summary?.upcomingBillsAmount ?? 0, locale)} detail={t("common.commitmentCount", { count: summary?.upcomingBillsCount ?? upcoming.length })} icon={ReceiptText} tone="amber" /></div>{queries.upcoming.error ? <ErrorState message={t("dashboard.upcomingUnavailable")} onRetry={() => { void queries.upcoming.refetch(); }} /> : <CashflowTimeline bills={upcoming} expenses={recent} locale={locale} />}{queries.recent.error ? <ErrorState message={t("dashboard.recentUnavailable")} onRetry={() => { void queries.recent.refetch(); }} /> : <div className="dashboard-grid"><section className="surface-card"><SectionHeading title={t("dashboard.upcomingTitle")} description={t("dashboard.nextDecisions")} action={<Link to="/dashboard/bills" className="inline-link">{t("common.viewAll")} <ArrowUpRight size={14} /></Link>} /><div className="compact-list">{upcoming.slice(0, 3).map((bill) => <Link to={`/dashboard/bills/${bill.id}`} className="compact-row" key={bill.id}><DataIcon type="bill" /><span><strong>{bill.description}</strong><small>{formatDate(bill.dueDate, locale)} · {t(categoryLabels[bill.category])}</small></span><span className="compact-row__amount"><strong>{formatCurrency(bill.amountDue, locale)}</strong><StatusPill status={bill.status} /></span></Link>)}{!upcoming.length && <EmptyState icon={ReceiptText} title={t("dashboard.noUpcoming")} description={t("dashboard.nextCommitments")} />}</div></section><section className="surface-card"><SectionHeading title={t("dashboard.recentTitle")} description={t("dashboard.selectedPeriodRead")} action={<Link to="/dashboard/expenses" className="inline-link">{t("common.viewAll")} <ArrowUpRight size={14} /></Link>} /><div className="recent-summary"><div className="recent-summary__chart"><KpiSparkline values={recent.length ? recent.slice(0, 8).map((item) => item.amount) : [0]} color="#23b89a" /><span><strong>{formatCurrency(spent, locale)}</strong><small>{t("common.transactionCount", { count: recent.length })}</small></span></div><div className="category-bars"><CategoryBar label={t("dashboard.foodHome")} value={categoryPercentage(recent, ["food", "housing"])} color="mint" /><CategoryBar label={t("dashboard.transport")} value={categoryPercentage(recent, ["transportation"])} color="blue" /><CategoryBar label={t("dashboard.personal")} value={categoryPercentage(recent, ["personal", "gifts"])} color="amber" /></div></div></section></div>}<section className="quick-actions"><QuickAction to="/dashboard/bills" icon={ReceiptText} label={t("bills.add")} detail={t("dashboard.keepCommitment")} /><QuickAction to="/dashboard/expenses" icon={ArrowDownRight} label={t("expenses.add")} detail={t("dashboard.recordExpense")} /><QuickAction to="/account/organization" icon={WalletCards} label={t("dashboard.setBudget")} detail={t("dashboard.monthBoundary")} /></section></>}</PageContainer>;
}

function categoryPercentage(items: DashboardExpense[], categoriesToCount: string[]) { const total = items.reduce((sum, item) => sum + item.amount, 0); return total ? Math.round(items.filter((item) => categoriesToCount.includes(item.category)).reduce((sum, item) => sum + item.amount, 0) / total * 100) : 0; }
function CategoryBar({ label, value, color }: { label: string; value: number; color: string }) { return <div className="category-bar"><span><i className={`tiny-dot tiny-dot--${color}`} />{label}</span><span>{value}%</span><div><i className={`category-bar__fill category-bar__fill--${color}`} style={{ width: `${Math.min(value * 1.8, 100)}%` }} /></div></div>; }
function CashflowTimeline({ bills, expenses, locale }: { bills: DashboardBill[]; expenses: DashboardExpense[]; locale: string }) { const { t } = useTranslation(); const events = [...bills.map((bill) => ({ date: bill.dueDate, label: bill.description, amount: bill.amountDue, kind: "bill" as const })), ...expenses.slice(0, 3).map((expense) => ({ date: expense.date, label: expense.description, amount: expense.amount, kind: "expense" as const }))].sort((a, b) => a.date.localeCompare(b.date)); return <section className="timeline-card"><div className="timeline-card__header"><div><p className="eyebrow">{t("dashboard.flow")}</p><h2>{t("dashboard.flowBody")}</h2></div><span className="timeline-card__legend"><i className="tiny-dot tiny-dot--amber" /> {t("dashboard.timelineCommitments")} <i className="tiny-dot tiny-dot--mint" /> {t("dashboard.timelineMoved")}</span></div><div className="timeline" role="list">{events.map((event, index) => <div className={`timeline-event timeline-event--${event.kind}`} key={`${event.date}-${event.label}`} role="listitem" style={{ "--event-index": index } as CSSProperties}><span className="timeline-event__date">{formatDate(event.date, locale)}</span><span className="timeline-event__dot" /><span className="timeline-event__label">{event.label}</span><strong>{event.kind === "expense" ? "−" : ""}{formatCurrency(event.amount, locale)}</strong></div>)}</div>{!events.length && <EmptyState icon={CircleDollarSign} title={t("dashboard.noMovement")} description={t("dashboard.timelineEmpty")} />}</section>; }

function BillsPage() {
  const { t } = useTranslation(); const locale = useLocale(); const organizationId = useSelectedOrganization(); const month = useCurrentMonth(); const [search, setSearch] = useState(""); const debouncedSearch = useDebounce(search); const [status, setStatus] = useState<BillStatus | "all">("all"); const [series, setSeries] = useState<BillSeriesType | "all">("all"); const [page, setPage] = useState(1); const [modal, setModal] = useState<"add" | "edit" | null>(null); const [selected, setSelected] = useState<Bill | null>(null); const query = useBillsQuery(organizationId ? { organizationId, page, pageSize: 20, from: month.from, to: month.to, status: status === "all" ? undefined : status, description: debouncedSearch } : null); const mutations = useBillMutations(organizationId); const rows = (query.data?.data ?? []).filter((bill) => series === "all" || bill.billSeriesType === series); const total = rows.reduce((sum, bill) => sum + bill.amountDue, 0); const due = rows.filter((bill) => ["due", "overdue"].includes(bill.status)).reduce((sum, bill) => sum + bill.amountDue, 0); const paid = rows.filter((bill) => bill.status === "paid").reduce((sum, bill) => sum + (bill.amountPaid ?? 0), 0); const clear = () => { setSearch(""); setStatus("all"); setSeries("all"); setPage(1); }; const remove = (id: string) => { if (window.confirm(t("common.deleteBillConfirm"))) mutations.remove.mutate(id, { onSuccess: () => toast.success(t("bills.removed")), onError: (error) => toast.error(error.message) }); }; const markPaid = (bill: Bill) => mutations.update.mutate({ id: bill.id, input: { description: bill.description, category: bill.category, status: "paid", dueDate: bill.dueDate, paymentDate: new Date().toISOString(), amountDue: bill.amountDue, amountPaid: bill.amountDue } }, { onSuccess: () => toast.success(t("bills.markedPaid")), onError: (error) => toast.error(error.message) });
  if (!organizationId) return <PageContainer><EmptyState icon={Building2} title={t("bills.selectOrganization")} description={t("bills.scoped")} /></PageContainer>;
  return <PageContainer><PageHeader eyebrow={t("bills.eyebrow")} title={t("bills.title")} description={t("bills.body")} actions={<Button onClick={() => setModal("add")}><Plus size={17} /> {t("bills.add")}</Button>} /><div className="stat-strip"><div><span>{t("bills.total")}</span><strong>{formatCurrency(total, locale)}</strong></div><div><span>{t("bills.due")}</span><strong className="text-amber">{formatCurrency(due, locale)}</strong></div><div><span>{t("bills.paid")}</span><strong className="text-mint">{formatCurrency(paid, locale)}</strong></div></div><div className="filter-bar"><label className="search-field"><Search size={17} /><input placeholder={t("bills.search")} value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} /></label><label className="select-field"><Filter size={15} /><select value={status} onChange={(event) => { setStatus(event.target.value as BillStatus | "all"); setPage(1); }}><option value="all">{t("bills.allStatuses")}</option>{["upcoming", "due", "overdue", "paid", "cancelled"].map((value) => <option value={value} key={value}>{t(`statuses.${value}`)}</option>)}</select></label><label className="select-field"><select value={series} onChange={(event) => setSeries(event.target.value as BillSeriesType | "all")}><option value="all">{t("bills.allTypes")}</option><option value="recurring">{t("bills.recurring")}</option><option value="installment">{t("bills.installments")}</option></select></label>{(search || status !== "all" || series !== "all") && <Button type="button" variant="ghost" className="clear-filters-button" onClick={clear}><RotateCcw size={15} /> {t("common.clearFilters")}</Button>}</div><section className="surface-card surface-card--table">{query.isPending ? <LoadingState /> : query.error ? <ErrorState message={query.error.message} onRetry={() => { void query.refetch(); }} /> : <><div className="table-head"><span>{t("bills.commitment")}</span><span>{t("bills.dueDate")}</span><span>{t("bills.type")}</span><span>{t("common.amount")}</span><span>{t("bills.status")}</span><span aria-label={t("common.actions")} /></div>{rows.length ? rows.map((bill) => <BillRow key={bill.id} bill={bill} locale={locale} onDetails={() => { setSelected(bill); setModal("edit"); }} onDelete={() => remove(bill.id)} onPaid={() => markPaid(bill)} />) : <EmptyState icon={ReceiptText} title={t("common.noResults")} description={t("bills.empty")} action={<Button variant="secondary" onClick={clear}>{t("common.clearFilters")}</Button>} />}</>}</section>{query.data && query.data.totalPages > 1 && <Pagination page={page} totalPages={query.data.totalPages} onPageChange={setPage} />}{modal === "add" && <BillModal onClose={() => setModal(null)} organizationId={organizationId} />}{modal === "edit" && selected && <BillModal bill={selected} onClose={() => { setModal(null); setSelected(null); }} organizationId={organizationId} />}</PageContainer>;
}

function Pagination({ page, totalPages, onPageChange }: { page: number; totalPages: number; onPageChange: (page: number) => void }) { const { t } = useTranslation(); return <div className="page-header__actions"><Button variant="secondary" disabled={page <= 1} onClick={() => onPageChange(page - 1)}>{t("common.previous")}</Button><span>{page} / {totalPages}</span><Button variant="secondary" disabled={page >= totalPages} onClick={() => onPageChange(page + 1)}>{t("common.next")}</Button></div>; }
function BillRow({ bill, locale, onDetails, onDelete, onPaid }: { bill: Bill; locale: string; onDetails: () => void; onDelete: () => void; onPaid: () => void }) { const { t } = useTranslation(); return <div className="table-row"><div className="table-row__primary"><DataIcon type="bill" /><span><strong>{bill.description}</strong><small>{t(categoryLabels[bill.category])}{bill.billSeriesType === "installment" && ` · ${t("common.installmentCount", { current: bill.occurrenceNumber, total: bill.totalOccurrences })}`}</small></span></div><span>{formatDate(bill.dueDate, locale)}<small>{relativeDate(bill.dueDate, locale)}</small></span><span>{bill.billSeriesType ? <span className="type-label"><i className={`tiny-dot tiny-dot--${bill.billSeriesType === "recurring" ? "blue" : "amber"}`} />{t(`types.${bill.billSeriesType}`)}</span> : <span className="muted">{t("common.oneTime")}</span>}</span><strong>{formatCurrency(bill.amountDue, locale)}</strong><StatusPill status={bill.status} /><div className="row-actions"><ActionMenu onEdit={onDetails} onPaid={onPaid} canPay={bill.status !== "paid"} detailHref={`/dashboard/bills/${bill.id}`} onDelete={onDelete} /></div></div>; }

function BillModal({ bill, onClose, organizationId }: { bill?: Bill; onClose: () => void; organizationId: string }) { const { t } = useTranslation(); const mutations = useBillMutations(organizationId); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const series = String(data.get("series") ?? "one-time"); const input = { description: String(data.get("description") ?? ""), category: String(data.get("category") ?? "miscellaneous") as BillCategory, status: (bill?.status ?? "upcoming") as BillStatus, dueDate: new Date(`${String(data.get("date"))}T12:00:00.000Z`).toISOString(), paymentDate: bill?.paymentDate ?? null, amountDue: Number(data.get("amount") ?? 0), amountPaid: bill?.amountPaid ?? null, frequency: series === "one-time" ? null : String(data.get("frequency") ?? "monthly") as BillFrequency, installments: series === "installment" ? Number(data.get("installments") ?? 1) : null }; const done = () => { toast.success(bill ? t("bills.updated") : t("bills.created")); onClose(); }; if (bill) mutations.update.mutate({ id: bill.id, input }, { onSuccess: done, onError: (error) => toast.error(error.message) }); else mutations.create.mutate(input, { onSuccess: done, onError: (error) => toast.error(error.message) }); }; return <Modal title={bill ? t("bills.edit") : t("bills.add")} description={t("bills.formDescription")} onClose={onClose}><form className="modal-form" onSubmit={submit}><label><span>{t("common.description")}</span><input name="description" defaultValue={bill?.description} required /></label><div className="form-grid"><label><span>{t("common.category")}</span><select name="category" defaultValue={bill?.category ?? "housing"}>{categories.map((value) => <option value={value} key={value}>{t(categoryLabels[value])}</option>)}</select></label><label><span>{t("common.amount")}</span><input name="amount" type="number" min="0" step="0.01" defaultValue={bill?.amountDue} required /></label></div><label><span>{t("bills.dueDate")}</span><input name="date" type="date" defaultValue={bill ? inputDate(bill.dueDate) : inputDate(new Date().toISOString())} required /></label>{!bill && <><label><span>{t("common.schedule")}</span><select name="series"><option value="one-time">{t("bills.oneTime")}</option><option value="recurring">{t("bills.recurring")}</option><option value="installment">{t("bills.installment")}</option></select></label><label><span>{t("common.frequency")}</span><select name="frequency" defaultValue="monthly"><option value="weekly">{t("bills.weekly")}</option><option value="monthly">{t("bills.monthly")}</option><option value="annually">{t("bills.annually")}</option></select></label><label><span>{t("common.installments")}</span><input name="installments" type="number" min="1" /></label></>}<div className="modal-form__actions"><Button type="button" variant="ghost" onClick={onClose}>{t("common.cancel")}</Button><Button type="submit" disabled={mutations.create.isPending || mutations.update.isPending}>{t("common.save")} <ArrowUpRight size={16} /></Button></div></form></Modal>; }

function BillDetailsPage() { const { t } = useTranslation(); const { billId } = useParams(); const organizationId = useSelectedOrganization(); const locale = useLocale(); const query = useBillQuery(organizationId, billId); const mutations = useBillMutations(organizationId); const inputRef = useRef<HTMLInputElement>(null); const [fileCategory, setFileCategory] = useState<FileCategory>("Other"); const bill = query.data; const upload = (file: File) => { const valid = acceptedDocumentTypes.split(",").some((type) => file.name.toLowerCase().endsWith(type.replace(".", ""))) && file.size <= 10 * 1024 * 1024; if (!valid) { toast.error(t("bills.invalidFile")); return; } if (billId) mutations.upload.mutate({ id: billId, file, category: fileCategory }, { onSuccess: () => toast.success(t("bills.uploaded")), onError: (error) => toast.error(error.message) }); }; const open = async (documentId: string) => { const blob = await billsService.getDocumentAsync(organizationId!, billId!, documentId); const url = URL.createObjectURL(blob); window.open(url, "_blank", "noopener,noreferrer"); window.setTimeout(() => URL.revokeObjectURL(url), 30_000); }; const download = async (documentId: string) => { const response = await billsService.getDocumentDownloadUrlAsync(organizationId!, billId!, documentId); window.open(response.url, "_blank", "noopener,noreferrer"); }; if (query.isPending) return <PageContainer><LoadingState /></PageContainer>; if (query.error || !bill) return <PageContainer><ErrorState message={query.error?.message ?? t("bills.notFound")} onRetry={() => { void query.refetch(); }} /></PageContainer>; return <PageContainer><Link to="/dashboard/bills" className="back-link">← {t("nav.bills")}</Link><PageHeader eyebrow={t("bills.detail")} title={bill.description} description={`${t(categoryLabels[bill.category])} · ${formatLongDate(bill.dueDate, locale)}`} actions={bill.status !== "paid" ? <Button disabled={mutations.update.isPending} onClick={() => mutations.update.mutate({ id: bill.id, input: { description: bill.description, category: bill.category, status: "paid", dueDate: bill.dueDate, paymentDate: new Date().toISOString(), amountDue: bill.amountDue, amountPaid: bill.amountDue } }, { onSuccess: () => toast.success(t("bills.markedPaid")), onError: (error) => toast.error(error.message) })}>{t("bills.markPaid")} <Check size={16} /></Button> : <StatusPill status="paid" />} /><div className="detail-grid"><section className="surface-card detail-card"><div className="detail-card__amount"><span>{t("bills.amountDue")}</span><strong>{formatCurrency(bill.amountDue, locale)}</strong><StatusPill status={bill.status} /></div><dl className="detail-list"><div><dt>{t("bills.dueDate")}</dt><dd>{formatLongDate(bill.dueDate, locale)}</dd></div><div><dt>{t("common.category")}</dt><dd>{t(categoryLabels[bill.category])}</dd></div><div><dt>{t("common.schedule")}</dt><dd>{bill.billSeriesType ? `${t(`types.${bill.billSeriesType}`)} · ${bill.occurrenceNumber ?? ""}` : t("common.oneTime")}</dd></div></dl>{bill.billSeriesId && bill.billSeriesIsActive && <Button variant="secondary" disabled={mutations.stopSeries.isPending} onClick={() => { if (window.confirm(t("common.stopFutureBillsConfirm"))) mutations.stopSeries.mutate(bill.billSeriesId!, { onSuccess: () => toast.success(t("bills.futureStopped")), onError: (error) => toast.error(error.message) }); }}>{t("bills.stopFuture")}</Button>}</section><section className="surface-card detail-card"><SectionHeading title={t("common.attachments")} description={t("bills.attachmentDescription")} action={<div><select aria-label={t("common.documentCategory")} value={fileCategory} onChange={(event) => setFileCategory(event.target.value as FileCategory)}>{documentCategories.map((value) => <option key={value}>{t(`documents.${value}`)}</option>)}</select><Button variant="secondary" onClick={() => inputRef.current?.click()}><FilePlus2 size={16} /> {t("common.addFile")}</Button><input ref={inputRef} type="file" accept={acceptedDocumentTypes} hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) upload(file); event.currentTarget.value = ""; }} /></div>} />{bill.documents.length ? bill.documents.map((document) => <div className="attachment-row" key={document.id}><DataIcon type="bill" /><span><strong>{document.fileName}</strong><small>{t(`documents.${document.fileCategory}`)}</small></span><Button variant="ghost" onClick={() => { void open(document.id); }}>{t("common.open")}</Button><Button variant="ghost" onClick={() => { void download(document.id); }}>{t("common.download")}</Button><IconButton label={t("common.removeFile", { name: document.fileName })} onClick={() => { if (window.confirm(t("common.removeDocumentConfirm"))) mutations.removeDocument.mutate({ billId: bill.id, documentId: document.id }, { onSuccess: () => toast.success(t("bills.documentRemoved")), onError: (error) => toast.error(error.message) }); }}><MoreHorizontal size={16} /></IconButton></div>) : <EmptyState icon={FilePlus2} title={t("bills.noAttachments")} description={t("bills.receiptHint")} />}</section></div></PageContainer>; }

function ExpensesPage() { const { t } = useTranslation(); const locale = useLocale(); const organizationId = useSelectedOrganization(); const month = useCurrentMonth(); const { user } = useAuth(); const [search, setSearch] = useState(""); const [status, setStatus] = useState<ExpenseStatus | "all">("all"); const [page, setPage] = useState(1); const [modal, setModal] = useState<"add" | "edit" | null>(null); const [selected, setSelected] = useState<Expense | null>(null); const query = useExpensesQuery(organizationId ? { organizationId, page, pageSize: 20, from: month.from, to: month.to } : null); const mutations = useExpenseMutations(organizationId); const rows = (query.data?.data ?? []).filter((expense) => expense.description.toLowerCase().includes(search.toLowerCase()) && (status === "all" || expense.status === status)); const total = rows.reduce((sum, expense) => sum + expense.amount, 0); const remove = (id: string) => { if (window.confirm(t("common.deleteExpenseConfirm"))) mutations.remove.mutate(id, { onSuccess: () => toast.success(t("expenses.removed")), onError: (error) => toast.error(error.message) }); }; if (!organizationId || !user) return <PageContainer><EmptyState icon={Building2} title={t("expenses.selectOrganization")} description={t("expenses.scoped")} /></PageContainer>; return <PageContainer><PageHeader eyebrow={t("expenses.eyebrow")} title={t("expenses.title")} description={t("expenses.body")} actions={<Button onClick={() => setModal("add")}><Plus size={17} /> {t("expenses.add")}</Button>} /><div className="stat-strip"><div><span>{t("expenses.total")}</span><strong>{formatCurrency(total, locale)}</strong></div><div><span>{t("expenses.transactions")}</span><strong>{rows.length}</strong></div><div><span>{t("expenses.average")}</span><strong>{formatCurrency(rows.length ? total / rows.length : 0, locale)}</strong></div></div><p className="page-header__description">{t("expenses.localFilters")}</p><div className="filter-bar"><label className="search-field"><Search size={17} /><input placeholder={t("expenses.search")} value={search} onChange={(event) => setSearch(event.target.value)} /></label><label className="select-field"><Filter size={15} /><select value={status} onChange={(event) => setStatus(event.target.value as ExpenseStatus | "all")}><option value="all">{t("expenses.allStatuses")}</option>{["paid", "pending", "cancelled"].map((value) => <option key={value} value={value}>{t(`statuses.${value}`)}</option>)}</select></label></div><section className="surface-card surface-card--table">{query.isPending ? <LoadingState /> : query.error ? <ErrorState message={query.error.message} onRetry={() => { void query.refetch(); }} /> : <><div className="table-head table-head--expenses"><span>{t("expenses.expense")}</span><span>{t("expenses.date")}</span><span>{t("expenses.category")}</span><span>{t("expenses.amount")}</span><span>{t("expenses.status")}</span><span aria-label={t("common.actions")} /></div>{rows.length ? rows.map((expense) => <ExpenseRow key={expense.id} expense={expense} locale={locale} onDetails={() => { setSelected(expense); setModal("edit"); }} onDelete={() => remove(expense.id)} />) : <EmptyState icon={BarChart3} title={t("common.noResults")} description={t("expenses.empty")} />}</>}</section>{query.data && query.data.totalPages > 1 && <Pagination page={page} totalPages={query.data.totalPages} onPageChange={setPage} />}{modal && <ExpenseModal expense={modal === "edit" ? selected ?? undefined : undefined} onClose={() => { setModal(null); setSelected(null); }} organizationId={organizationId} userId={user.id} />}</PageContainer>; }
function ExpenseRow({ expense, locale, onDetails, onDelete }: { expense: Expense; locale: string; onDetails: () => void; onDelete: () => void }) { const { t } = useTranslation(); return <div className="table-row table-row--expense"><div className="table-row__primary"><DataIcon type="expense" /><span><strong>{expense.description}</strong><small>{t("expenses.added", { date: relativeDate(expense.occurredAt, locale) })}</small></span></div><span>{formatDate(expense.occurredAt, locale)}</span><span><span className="type-label"><i className="tiny-dot tiny-dot--mint" />{t(categoryLabels[expense.category])}</span></span><strong>{formatCurrency(expense.amount, locale)}</strong><StatusPill status={expense.status} /><div className="row-actions"><ActionMenu onEdit={onDetails} detailHref={`/dashboard/expenses/${expense.id}`} onDelete={onDelete} /></div></div>; }
function ExpenseModal({ expense, onClose, organizationId, userId }: { expense?: Expense; onClose: () => void; organizationId: string; userId: string }) { const { t } = useTranslation(); const mutations = useExpenseMutations(organizationId); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const input = { description: String(data.get("description") ?? ""), category: String(data.get("category") ?? "miscellaneous") as ExpenseCategory, amount: Number(data.get("amount") ?? 0), status: (expense?.status ?? "paid") as ExpenseStatus, occurredAt: new Date(`${String(data.get("date"))}T12:00:00.000Z`).toISOString() }; const done = () => { toast.success(expense ? t("expenses.updated") : t("expenses.created")); onClose(); }; if (expense) mutations.update.mutate({ id: expense.id, input }, { onSuccess: done, onError: (error) => toast.error(error.message) }); else mutations.create.mutate({ ...input, createdBy: userId }, { onSuccess: done, onError: (error) => toast.error(error.message) }); }; return <Modal title={expense ? t("expenses.edit") : t("expenses.add")} description={t("expenses.formDescription")} onClose={onClose}><form className="modal-form" onSubmit={submit}><label><span>{t("common.description")}</span><input name="description" defaultValue={expense?.description} required /></label><div className="form-grid"><label><span>{t("common.category")}</span><select name="category" defaultValue={expense?.category ?? "food"}>{categories.map((value) => <option value={value} key={value}>{t(categoryLabels[value])}</option>)}</select></label><label><span>{t("common.amount")}</span><input name="amount" type="number" min="0" step="0.01" defaultValue={expense?.amount} required /></label></div><label><span>{t("common.date")}</span><input name="date" type="date" defaultValue={expense ? inputDate(expense.occurredAt) : inputDate(new Date().toISOString())} required /></label><div className="modal-form__actions"><Button type="button" variant="ghost" onClick={onClose}>{t("common.cancel")}</Button><Button type="submit" disabled={mutations.create.isPending || mutations.update.isPending}>{expense ? t("common.save") : t("expenses.add")} <ArrowUpRight size={16} /></Button></div></form></Modal>; }
function ExpenseDetailsPage() { const { t } = useTranslation(); const { expenseId } = useParams(); const organizationId = useSelectedOrganization(); const locale = useLocale(); const query = useExpenseQuery(organizationId, expenseId); const mutations = useExpenseMutations(organizationId); const inputRef = useRef<HTMLInputElement>(null); const [fileCategory, setFileCategory] = useState<FileCategory>("Receipt"); const expense = query.data; const upload = (file: File) => { const valid = acceptedDocumentTypes.split(",").some((type) => file.name.toLowerCase().endsWith(type.replace(".", ""))) && file.size <= 10 * 1024 * 1024; if (!valid) { toast.error(t("bills.invalidFile")); return; } if (expenseId) mutations.upload.mutate({ id: expenseId, file, category: fileCategory }, { onSuccess: () => toast.success(t("bills.uploaded")), onError: (error) => toast.error(error.message) }); }; const open = async (documentId: string) => { const blob = await expensesService.getDocumentAsync(organizationId!, expenseId!, documentId); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "expense-document"; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 30_000); }; if (query.isPending) return <PageContainer><LoadingState /></PageContainer>; if (query.error || !expense) return <PageContainer><ErrorState message={query.error?.message ?? t("expenses.notFound")} onRetry={() => { void query.refetch(); }} /></PageContainer>; return <PageContainer><Link to="/dashboard/expenses" className="back-link">← {t("nav.expenses")}</Link><PageHeader eyebrow={t("expenses.detail")} title={expense.description} description={`${t(categoryLabels[expense.category])} · ${formatLongDate(expense.occurredAt, locale)}`} actions={<StatusPill status={expense.status} />} /><div className="detail-grid"><section className="surface-card detail-card"><div className="detail-card__amount"><span>{t("expenses.amount")}</span><strong>{formatCurrency(expense.amount, locale)}</strong><StatusPill status={expense.status} /></div><dl className="detail-list"><div><dt>{t("expenses.occurred")}</dt><dd>{formatLongDate(expense.occurredAt, locale)}</dd></div><div><dt>{t("common.category")}</dt><dd>{t(categoryLabels[expense.category])}</dd></div><div><dt>{t("expenses.createdBy")}</dt><dd>{expense.createdBy}</dd></div></dl></section><section className="surface-card detail-card"><SectionHeading title={t("common.attachments")} description={t("expenses.attachmentDescription")} action={<div><select aria-label={t("common.documentCategory")} value={fileCategory} onChange={(event) => setFileCategory(event.target.value as FileCategory)}>{documentCategories.map((value) => <option key={value}>{t(`documents.${value}`)}</option>)}</select><Button variant="secondary" onClick={() => inputRef.current?.click()}><FilePlus2 size={16} /> {t("common.addFile")}</Button><input ref={inputRef} type="file" accept={acceptedDocumentTypes} hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) upload(file); event.currentTarget.value = ""; }} /></div>} />{expense.documents.length ? expense.documents.map((document) => <div className="attachment-row" key={document.id}><DataIcon type="expense" /><span><strong>{document.fileName}</strong><small>{t(`documents.${document.fileCategory}`)}</small></span><Button variant="ghost" onClick={() => { void open(document.id); }}>{t("common.download")}</Button><IconButton label={t("common.removeFile", { name: document.fileName })} onClick={() => { if (window.confirm(t("common.removeDocumentConfirm"))) mutations.removeDocument.mutate({ expenseId: expense.id, attachmentId: document.id }, { onSuccess: () => toast.success(t("bills.documentRemoved")), onError: (error) => toast.error(error.message) }); }}><MoreHorizontal size={16} /></IconButton></div>) : <EmptyState icon={FilePlus2} title={t("expenses.noAttachments")} description={t("expenses.receiptHint")} />}</section></div></PageContainer>; }

// The form mirrors a newly selected server record; this synchronization is intentional.
// eslint-disable-next-line react-hooks/set-state-in-effect
function OrganizationPage() { const { t } = useTranslation(); const locale = useLocale(); const organizationId = useSelectedOrganization(); const detail = useOrganizationQuery(organizationId); const budgetQuery = useBudgetQuery(organizationId); const mutations = useOrganizationMutations(organizationId); const [name, setName] = useState(""); const [budget, setBudget] = useState(""); useEffect(() => { if (detail.data) { setName(detail.data.name); setBudget(String(budgetQuery.data?.amount ?? detail.data.budget?.amount ?? "")); } }, [budgetQuery.data, detail.data]); if (!organizationId || detail.isPending) return <PageContainer><LoadingState /></PageContainer>; if (detail.error || !detail.data) return <PageContainer><ErrorState message={detail.error?.message ?? t("organization.notFound")} onRetry={() => { void detail.refetch(); }} /></PageContainer>; const organization = detail.data; const budgetData = budgetQuery.data !== undefined ? budgetQuery.data : organization.budget; return <PageContainer><PageHeader eyebrow={t("organization.eyebrow")} title={t("organization.title")} description={t("organization.body")} actions={<Link to="/organization/members" className="button button--secondary"><UsersRound size={17} /> {t("nav.members")}</Link>} /><div className="organization-layout"><section className="surface-card organization-hero"><div className="organization-hero__mark"><Building2 size={25} /></div><div><p className="eyebrow">{t("organization.active")}</p><h2>{organization.name}</h2><p>{t("organization.created", { date: formatLongDate(organization.createdAt, locale) })}</p></div><span className="organization-hero__status"><span className="live-dot" /> {t("common.active")}</span></section><div className="organization-grid"><section className="surface-card"><SectionHeading title={t("organization.settings")} description={t("organization.onlyEditable")} /><form className="modal-form" onSubmit={(event) => { event.preventDefault(); mutations.update.mutate(name, { onSuccess: () => toast.success(t("organization.settingsSaved")), onError: (error) => toast.error(error.message) }); }}><label><span>{t("organization.name")}</span><input value={name} onChange={(event) => setName(event.target.value)} required /></label><Button type="submit" disabled={mutations.update.isPending}>{t("common.save")} <Check size={16} /></Button></form></section><section className="surface-card budget-card"><SectionHeading title={t("organization.budget")} description={t("organization.boundary")} /><div className="budget-card__number"><span>{t("organization.monthlyLimit")}</span><strong>{budgetData ? formatCurrency(budgetData.amount, locale) : t("organization.notConfigured")}</strong></div><form className="inline-form" onSubmit={(event) => { event.preventDefault(); mutations.budget.mutate(Number(budget), { onSuccess: () => toast.success(t("organization.budgetSaved")), onError: (error) => toast.error(error.message) }); }}><input aria-label={t("organization.monthlyBudget")} type="number" min="0" step="0.01" value={budget} onChange={(event) => setBudget(event.target.value)} /><Button type="submit" disabled={mutations.budget.isPending}>{t("common.update")}</Button></form><div className="budget-card__footer"><span><CircleDollarSign size={15} /> {t("organization.dashboardUpdate")}</span></div></section></div><section className="surface-card organization-members-preview"><SectionHeading title={t("organization.members")} description={t("organization.memberBody")} action={<Link to="/organization/members" className="inline-link">{t("organization.manageMembers")} <ArrowUpRight size={14} /></Link>} /><div className="member-stack">{organization.members.slice(0, 3).map((member) => <div className="member-chip" key={member.id}><Avatar initials={member.username.slice(0, 2).toUpperCase()} size="sm" /><span><strong>{member.username}</strong><small>{member.email}</small></span></div>)}</div></section></div></PageContainer>; }

function MembersPage() {
  const { t } = useTranslation();
  const locale = useLocale();
  const auth = useAuth();
  const navigate = useNavigate();
  const organizationId = useSelectedOrganization();
  const detail = useOrganizationQuery(organizationId);
  const memberMutations = useOrganizationMemberMutations(organizationId);
  const [inviteOpen, setInviteOpen] = useState(false);
  const [invite, setInvite] = useState<{ url: string; expiresAt: string } | null>(null);
  const currentMember = detail.data?.members.find((member) => member.id === auth.user?.id);
  const currentRole = isKnownMemberRole(currentMember?.role) ? currentMember.role : undefined;
  const inviteRoles: Array<"Admin" | "Member"> = currentRole === "Owner" ? ["Admin", "Member"] : ["Member"];
  const canInvite = currentRole === "Owner" || currentRole === "Admin";
  const createInvite = useMutation({
    mutationFn: ({ email, role }: { email: string; role: "Admin" | "Member" }) => organizationsService.createInviteAsync(organizationId!, email, role),
    onSuccess: (result) => {
      setInvite({ url: `${window.location.origin}/join-organization?token=${encodeURIComponent(result.token)}`, expiresAt: result.expiresAt });
      setInviteOpen(false);
      toast.success(t("organization.invitationCreated"));
    },
    onError: (error) => toast.error(error instanceof Error ? error.message : t("organization.invitationError")),
  });

  if (!organizationId || detail.isPending) return <PageContainer><LoadingState /></PageContainer>;
  if (detail.error || !detail.data) return <PageContainer><ErrorState message={detail.error?.message ?? t("organization.membersUnavailable")} onRetry={() => { void detail.refetch(); }} /></PageContainer>;

  const copy = async () => {
    if (invite) {
      await navigator.clipboard.writeText(invite.url);
      toast.success(t("organization.invitationCopied"));
    }
  };
  const canChangeRole = (member: typeof detail.data.members[number]) => currentRole === "Owner" && isEditableMemberRole(member.role);
  const canRemove = (member: typeof detail.data.members[number]) => member.id === auth.user?.id || (currentRole === "Owner" && isEditableMemberRole(member.role)) || (currentRole === "Admin" && member.role === "Member");
  const removeMember = (member: typeof detail.data.members[number]) => {
    const isSelf = member.id === auth.user?.id;
    const confirmed = window.confirm(isSelf ? t("common.leaveOrganizationConfirm") : t("common.removeMemberConfirm", { name: member.username }));
    if (!confirmed) return;
    memberMutations.remove.mutate(member.id, {
      onSuccess: async () => {
        if (!isSelf) {
          toast.success(t("organization.memberRemoved"));
          return;
        }
        const nextUser = await auth.refreshUser();
        const nextOrganization = nextUser.organizations.find((organization) => organization.id !== organizationId);
        useOrganizationStore.getState().setSelectedOrganizationId(nextOrganization?.id ?? null);
        toast.success(t("organization.left"));
        navigate(nextOrganization ? "/dashboard" : "/account/create-organization", { replace: true });
      },
      onError: (error) => toast.error(error instanceof Error ? error.message : t("organization.removeError")),
    });
  };

  return <PageContainer>
    <PageHeader eyebrow={t("organization.eyebrow")} title={t("organization.membersTitle")} description={t("organization.membersBody")} actions={canInvite ? <Button onClick={() => setInviteOpen(true)}><UserPlus size={17} /> {t("common.invite")}</Button> : undefined} />
    <section className="surface-card members-card">
      <div className="members-card__summary"><div><span className="eyebrow">{t("organization.accessOverview")}</span><strong>{t("common.peopleCount", { count: detail.data.members.length })}</strong><p>{t("organization.everyoneAccess")}</p></div><span className="members-card__badge"><ShieldCheck size={15} /> {t("organization.protected")}</span></div>
      <div className="members-list">{detail.data.members.map((member) => {
        const role = isKnownMemberRole(member.role) ? member.role : null;
        const roleClass = role ? role.toLowerCase() : "unknown";
        return <div className="member-row" key={member.id}>
          <Avatar initials={member.username.slice(0, 2).toUpperCase()} size="md" />
          <span><strong>{member.username}</strong><small>{member.email}</small></span>
          <span className={`role-badge role-badge--${roleClass}`}>{role ? t(`roles.${role}`) : t("organization.roleUnavailable")}</span>
          <small className="member-row__joined">{member.joinedAt ? t("common.joined", { date: formatLongDate(member.joinedAt, locale) }) : t("organization.joinedUnavailable")}</small>
          {(canChangeRole(member) || canRemove(member)) && <div className="member-row__actions">
            {canChangeRole(member) && <select aria-label={`${t("organization.roleFor")} ${member.username}`} value={isEditableMemberRole(role) ? role : "Member"} disabled={memberMutations.updateRole.isPending} onChange={(event) => memberMutations.updateRole.mutate({ userId: member.id, role: event.target.value as "Admin" | "Member" }, { onSuccess: () => toast.success(t("organization.roleUpdated")), onError: (error) => toast.error(error instanceof Error ? error.message : t("organization.roleError")) })}><option value="Admin">{t("roles.Admin")}</option><option value="Member">{t("roles.Member")}</option></select>}
            {canRemove(member) && <Button variant="ghost" disabled={memberMutations.remove.isPending} onClick={() => removeMember(member)}>{member.id === auth.user?.id ? t("organization.leave") : t("organization.remove")}</Button>}
          </div>}
        </div>;
      })}</div>
    </section>
    {invite && <section className="surface-card detail-card"><SectionHeading title={t("organization.invitationReady")} description={t("common.expires", { date: formatLongDate(invite.expiresAt, locale) })} action={<Button onClick={() => { void copy(); }}>{t("common.copy")}</Button>} /><input readOnly value={invite.url} aria-label={t("organization.invitationLink")} /></section>}
    {inviteOpen && canInvite && <Modal title={t("common.invite")} description={t("organization.invitationDescription")} onClose={() => setInviteOpen(false)}><form className="modal-form" onSubmit={(event) => { event.preventDefault(); const data = new FormData(event.currentTarget); createInvite.mutate({ email: String(data.get("email")), role: String(data.get("role")) as "Admin" | "Member" }); }}><label><span>{t("organization.email")}</span><input name="email" type="email" required /></label><label><span>{t("organization.role")}</span><select name="role" defaultValue={inviteRoles[0]}>{inviteRoles.map((role) => <option key={role} value={role}>{t(`roles.${role}`)}</option>)}</select></label><div className="modal-form__actions"><Button type="button" variant="ghost" onClick={() => setInviteOpen(false)}>{t("common.cancel")}</Button><Button type="submit" disabled={createInvite.isPending}>{t("common.invite")} <ArrowUpRight size={16} /></Button></div></form></Modal>}
  </PageContainer>;
}

function AccountPage() {
  const { t, i18n } = useTranslation(); const auth = useAuth(); const navigate = useNavigate(); const mutations = useAccountMutations(); const user = auth.user;
  const organizationId = useSelectedOrganization(); const notificationPreferences = useNotificationPreferencesQuery(organizationId); const notificationMutations = useNotificationMutations(organizationId);
  const [firstName, setFirstName] = useState(user?.fullName.split(" ")[0] ?? ""); const [lastName, setLastName] = useState(user?.fullName.split(" ").slice(1).join(" ") ?? "");
  const { theme, setTheme } = useTheme(); const avatarInput = useRef<HTMLInputElement>(null);
  if (!user) return null;
  const save = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); try { await mutations.profile.mutateAsync({ firstName, lastName }); await auth.refreshUser(); toast.success(t("account.profileSaved")); } catch (error) { toast.error(error instanceof Error ? error.message : t("account.unableSave")); } };
  const upload = async (file: File) => {
    if (!acceptedAvatarTypes.includes(file.type) || file.size > 2 * 1024 * 1024) { toast.error(t("account.invalidAvatar")); return; }
    try {
      await mutations.avatar.mutateAsync(file);
      // The backend has no avatar-read endpoint, so the object URL is session-local.
      auth.setAvatarPreview(file);
      await auth.refreshUser();
      toast.success(t("account.avatarUpdated"));
    } catch (error) { toast.error(error instanceof Error ? error.message : t("account.unableUpload")); }
  };
  return <PageContainer><PageHeader eyebrow={t("account.eyebrow")} title={t("account.title")} description={t("account.body")} /><div className="account-layout"><section className="surface-card profile-card"><SectionHeading title={t("account.profile")} description={t("account.profileDescription")} /><div className="profile-card__identity"><Avatar initials={firstName.slice(0, 1) + lastName.slice(0, 1)} src={user.avatarUrl ?? undefined} size="lg" /><div><strong>{user.fullName}</strong><span>{user.email}</span></div><Button variant="secondary" onClick={() => avatarInput.current?.click()}>{t("account.changeAvatar")}</Button><input ref={avatarInput} hidden type="file" accept="image/jpeg,image/png" onChange={(event) => { const file = event.target.files?.[0]; if (file) void upload(file); event.currentTarget.value = ""; }} /></div><form className="form-grid account-form" onSubmit={(event) => { void save(event); }}><label><span>{t("auth.firstName")}</span><input value={firstName} onChange={(event) => setFirstName(event.target.value)} required /></label><label><span>{t("auth.lastName")}</span><input value={lastName} onChange={(event) => setLastName(event.target.value)} required /></label><Button type="submit" disabled={mutations.profile.isPending}>{t("common.save")} <Check size={16} /></Button></form><Button variant="ghost" onClick={() => { if (window.confirm(t("common.removeAvatarConfirm"))) mutations.deleteAvatar.mutate(undefined, { onSuccess: () => { auth.clearAvatarPreview(); void auth.refreshUser(); toast.success(t("account.avatarRemoved")); }, onError: (error) => toast.error(error.message) }); }}>{t("account.removeAvatar")}</Button></section><section className="surface-card preferences-card"><SectionHeading title={t("account.appearance")} description={t("account.reset")} /><div className="preference-row"><span><Globe2 size={17} /><span><strong>{t("account.language")}</strong><small>{t("account.languageDescription")}</small></span></span><select value={i18n.language} onChange={(event) => { void i18n.changeLanguage(event.target.value); localStorage.setItem("bitfinance-v2-locale", event.target.value); }}><option value="en-US">{t("common.english")}</option><option value="pt-BR">{t("common.portuguese")}</option></select></div><div className="preference-row"><span><SunMedium size={17} /><span><strong>{t("account.theme")}</strong><small>{t("account.themeDescription")}</small></span></span><span className="theme-pills"><button type="button" className={`theme-pill ${theme === "light" ? "theme-pill--active" : ""}`} onClick={() => setTheme("light")}>{t("common.light")}</button><button type="button" className={`theme-pill ${theme === "dark" ? "theme-pill--active" : ""}`} onClick={() => setTheme("dark")}>{t("common.dark")}</button></span></div><div className="preference-row"><span><Mail size={17} /><span><strong>{t("account.billReminderEmails")}</strong><small>{notificationPreferences.data?.emailAvailable ? t("account.billReminderEmailsDescription") : t("account.billReminderEmailsUpgrade")}</small></span></span><label className="switch"><input type="checkbox" checked={notificationPreferences.data?.emailBillRemindersEnabled ?? false} disabled={!notificationPreferences.data?.emailAvailable || notificationMutations.updatePreferences.isPending} onChange={(event) => notificationMutations.updatePreferences.mutate(event.target.checked, { onError: (error) => toast.error(error.message) })} /><span /></label></div><div className="account-signout"><Button variant="danger" onClick={() => { void auth.signOut().then(() => navigate("/auth/sign-in", { replace: true })); }}>{t("account.signOut")}</Button><Button variant="ghost" onClick={() => { if (window.confirm(t("common.signOutAllConfirm"))) void auth.signOut(true).then(() => navigate("/auth/sign-in", { replace: true })); }}>{t("account.signOutAll")}</Button></div></section></div></PageContainer>;
}
function MorePage() { const { t } = useTranslation(); return <PageContainer><PageHeader eyebrow={t("more.eyebrow")} title={t("more.title")} description={t("more.body")} /><div className="more-grid"><QuickAction to="/account/organization" icon={Building2} label={t("nav.organization")} detail={t("more.budgetSettings")} /><QuickAction to="/organization/members" icon={UsersRound} label={t("nav.members")} detail={t("more.access")} /><QuickAction to="/account/settings" icon={Settings2} label={t("nav.account")} detail={t("more.profilePreferences")} /></div></PageContainer>; }
function NotFoundPage() { const { t } = useTranslation(); return <PublicLayout><main className="center-page"><div className="center-card"><span className="center-card__icon"><Search size={25} /></span><p className="eyebrow">{t("common.notFound")}</p><h1>{t("common.pageMoved")}</h1><p>{t("common.findFinanceDesk")}</p><Link to="/dashboard" className="button button--primary">{t("common.backToDesk")} <ArrowRight size={16} /></Link></div></main></PublicLayout>; }
